SELECT 
  FROM projects
 WHERE id = #{projectId}
   AND owner_id = #{ownerId}
   AND archived_at IS NULL

SELECT 
  FROM projects
 WHERE id = #{projectId}
   AND owner_id = #{ownerId}
   AND archived_at IS NULL
 FOR UPDATE

SELECT 
  FROM projects
 WHERE owner_id = #{ownerId}
   AND archived_at IS NULL
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}

SELECT 
  FROM projects
 WHERE owner_id = #{ownerId}
   AND archived_at IS NULL
   AND (updated_at < #{updatedAt}
        OR (updated_at = #{updatedAt} AND id < #{id}))
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}
